import { useCallback, useState } from 'react';
import { Button, Drawer, Menu, MenuItem, MenuSeparator } from '@jinx-ui/react';

type NavKey = 'projects' | 'team' | 'settings' | 'logout';

type SideNavProps = {
  onNavigate: (key: NavKey) => void;
};

const items: { key: NavKey; label: string }[] = [
  { key: 'projects', label: 'Проекты' },
  { key: 'team', label: 'Команда' },
  { key: 'settings', label: 'Настройки' },
];

export default function SideNav({ onNavigate }: SideNavProps) {
  const [open, setOpen] = useState(false);

  const select = useCallback(
    (key: NavKey) => {
      onNavigate(key);
      setOpen(false);
    },
    [onNavigate],
  );

  return (
    <>
      <Button
        className="jx-button"
        aria-haspopup="dialog"
        aria-expanded={open}
        onClick={() => setOpen(true)}
      >
        Меню
      </Button>

      <Drawer
        open={open}
        side="left"
        onClose={() => setOpen(false)}
        aria-label="Навигация"
        className="jx-drawer"
      >
        <Menu
          className="jx-menu"
          aria-label="Разделы"
          style={{ display: 'grid', gap: 'var(--jx-space-1)', padding: 'var(--jx-space-2)' }}
        >
          {items.map((item) => (
            <MenuItem key={item.key} className="jx-menu-item" onSelect={() => select(item.key)}>
              {item.label}
            </MenuItem>
          ))}
          <MenuSeparator className="jx-menu-separator" />
          <MenuItem
            className="jx-menu-item"
            tone="danger"
            onSelect={() => select('logout')}
            style={{ color: 'var(--jx-color-danger)' }}
          >
            Выйти
          </MenuItem>
        </Menu>
      </Drawer>
    </>
  );
}

